def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); pts=[]
            while stack:
                a,b=stack.pop(); pts.append((a,b))
                for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                    if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==color:
                        seen.add((x,y)); stack.append((x,y))
            objs.append(pts)
    touching=[p for p in objs if any(r==0 or c==0 or r==h-1 or c==w-1 for r,c in p)]
    def area(p): return (max(r for r,c in p)-min(r for r,c in p)+1)*(max(c for r,c in p)-min(c for r,c in p)+1)
    p=max(touching or objs,key=area)
    r0=min(r for r,c in p); r1=max(r for r,c in p); c0=min(c for r,c in p); c1=max(c for r,c in p)
    return [row[c0:c1+1] for row in grid[r0:r1+1]]

